124	static ssize_t bk7258_dvfs_read(struct file *filep, char *buffer,
125	                                size_t buflen)
126	{
127	  struct bk7258_dvfs_file_s *priv = filep->f_priv;
128	  size_t totalsize;
129	  size_t copysize;
130	  size_t remaining;
131	  off_t  offset = filep->f_pos;
132	
133	  if (priv == NULL)
134	    {
135	      return -EIO;
136	    }
137	
138	  remaining = buflen;
139	  totalsize = 0;
140	
141	  priv->linesize = snprintf(priv->line, BK7258_DVFS_LINELEN,
142	                            "cur_freq %d\n", bk7258_dvfs_get_freq());
143	  copysize = procfs_memcpy(priv->line, priv->linesize, buffer, remaining,
144	                           &offset);
145	  totalsize += copysize;
146	
147	  if (totalsize > 0)
148	    {
149	      filep->f_pos += totalsize;
150	    }
151	
152	  return totalsize;
153	}
