155	static ssize_t bk7258_dvfs_write(struct file *filep, const char *buffer,
156	                                 size_t buflen)
157	{
158	  char line[BK7258_DVFS_LINELEN];
159	  char cmd[16];
160	  int  n;
161	  int  tier;
162	
163	  n = MIN(buflen, sizeof(line) - 1);
164	  strlcpy(line, buffer, (size_t)n + 1);
165	
166	  n = strcspn(line, " ");                    /* index of the space separator */
167	  n = MIN((unsigned)n, sizeof(cmd) - 1);
168	  strlcpy(cmd, line, (size_t)n + 1);
169	
170	  if (strcmp(cmd, "cur_freq") == 0)
171	    {
172	      tier = atoi(line + n + 1);             /* parse integer after the space */
173	      bk7258_dvfs_set_freq(tier);
174	    }
175	
176	  return (ssize_t)buflen;
177	}
